# 解析算法：三位数反向输出
x = int(input("请输入一个三位数: "))
x1 = int(x / 100)          # 百位
x2 = int((x - x1 * 100) / 10)  # 十位
x3 = x - x1 * 100 - x2 * 10    # 个位
y = x3 * 100 + x2 * 10 + x1
print(f"反向输出: {y}")

