# 模拟一个简单的信息处理系统

# 1. 信息采集（模拟传感器数据）
sensor_data = {
    '温度': 25.5,
    '湿度': 60,
    'PM2.5': 35
}

# 2. 信息处理
def analyze_air_quality(pm25):
    if pm25 <= 35:
        return "优"
    elif pm25 <= 75:
        return "良"
    elif pm25 <= 115:
        return "轻度污染"
    else:
        return "中度污染及以上"

# 3. 信息输出
print("=== 环境监测系统 ===")
for key, value in sensor_data.items():
    print(f"{key}: {value}")

aqi = analyze_air_quality(sensor_data['PM2.5'])
print(f"空气质量: {aqi}")

