# 2. 简单数据加密（凯撒密码示例）
def caesar_encrypt(text, shift=3):
    result = ""
    for char in text:
        # 只处理 ASCII 字母：汉字的 .isalpha() 也是 True，
        # 会被下面的模运算换成别的字符，
        # 于是加密完再解密就回不到原文。
        if char.isascii() and char.isalpha():
            # 大写字母
            if char.isupper():
                result += chr((ord(char) - 65 + shift) % 26 + 65)
            # 小写字母
            else:
                result += chr((ord(char) - 97 + shift) % 26 + 97)
        else:
            result += char
    return result

def caesar_decrypt(text, shift=3):
    return caesar_encrypt(text, -shift)

original = "Hello甘肃"
encrypted = caesar_encrypt(original)
decrypted = caesar_decrypt(encrypted)
print(f"\n原文: {original}")
print(f"加密: {encrypted}")
print(f"解密: {decrypted}")

# 3. 密码强度检测
def check_password_strength(password):
    score = 0
    if len(password) >= 8:
        score += 1
    if password.isdigit():
        score += 1  # 纯数字
    if password.isalpha():
        score += 1  # 纯字母
    if any(c.isupper() for c in password) and any(c.islower() for c in password):
        score += 1  # 大小写混合
    if any(not c.isalnum() for c in password):
        score += 1  # 含特殊字符

    if score <= 1:
        return "弱"
    elif score <= 3:
        return "中"
    else:
        return "强"

print(f"\n密码'123456'强度: {check_password_strength('123456')}")
print(f"密码'Abc123!@#'强度: {check_password_strength('Abc123!@#')}")
